29	/// Environment override for [`DEFAULT_LOG_MAX_BYTES`]; `0` disables the bound.
30	pub const LOG_MAX_BYTES_ENV: &str = "HERMIT_LOG_MAX_BYTES";
31	
32	/// Ceiling on one run's log file.
33	///
34	/// A run that makes no progress still logs. Measured 2026-08-11 over the 4111
35	/// retained `--verify` comparison logs on one host: p50 0.4 MiB, p90 43.5 MiB,
36	/// p99 145.5 MiB -- and then a tail to 928.8 GiB, 4357.4 GiB in total. The
37	/// largest single file was a KVM guest livelocked on `sched_yield`, logging the
38	/// same fifteen line shapes for 11.7 hours; its registers at the 50 GiB and
39	/// 900 GiB offsets were identical.
40	///
41	/// 1 GiB is about 7x p99, so it never truncates a log anyone reads, and it
42	/// removes 98.6% of those bytes while touching 0.56% of the files. The
43	/// distribution is bimodal enough that any bound from 0.25 to 16 GiB reclaims
44	/// over 94%, so this is a safety limit rather than a tuning parameter.
45	///
46	/// Compression is NOT the control. `/tmp` happens to be zstd-compressed here,
47	/// which is why a terabyte of repetitive DETLOG has been survivable, but a
48	/// compression ratio scales with how repetitive the runaway happens to be and
49	/// silently converts a hard failure into an invisible one.
50	pub const DEFAULT_LOG_MAX_BYTES: u64 = 1 << 30;
51	
52	/// Written once, in-band, when the bound is reached.
53	///
54	/// A truncated log MUST say so. Output that simply stops reads as a run that
55	/// ENDED, which would be a worse evidence defect than the disk hazard this
56	/// bound removes: a reader would draw conclusions from an absence we created.
57	///
58	/// The surrounding newlines are load-bearing, not cosmetic. The marker must
59	/// occupy a LINE OF ITS OWN at the very END of the file, because that is what
60	/// [`detcore::logdiff::log_was_truncated`] anchors on to tell a truncated log
61	/// apart from a log that merely quotes the text. This literal is deliberately
62	/// NOT `detcore::logdiff::TRUNCATION_MARKER` itself: keeping the two texts
63	/// independent is what leaves
64	/// `the_written_marker_is_the_text_the_comparator_matches` able to fail.
65	const TRUNCATION_MARKER: &[u8] =
66	    b"\n=== HERMIT LOG TRUNCATED: reached the configured size bound (HERMIT_LOG_MAX_BYTES). \
67	Output beyond this point was DISCARDED. The run itself continued and was NOT affected. ===\n";
68	
69	/// Resolve the configured ceiling; `0` means unlimited.
70	///
71	/// A malformed value is an ERROR rather than a fallback. Silently substituting
72	/// the 1 GiB default would mean `HERMIT_LOG_MAX_BYTES=unlimited`, or any typo
73	/// in the value used to disable the bound, quietly re-enabled it -- i.e. the
74	/// documented way to turn the bound off is one keystroke away from turning it
75	/// back on without saying so.
76	pub fn log_max_bytes() -> Result<u64, String> {
77	    match std::env::var(LOG_MAX_BYTES_ENV) {
78	        Ok(raw) => raw.trim().parse().map_err(|_| {
79	            format!(
80	                "{LOG_MAX_BYTES_ENV}={raw:?} is not a byte count. Set a non-negative integer \
81	                 number of bytes, or 0 to disable the bound."
82	            )
83	        }),
84	        Err(_) => Ok(DEFAULT_LOG_MAX_BYTES),
85	    }
86	}
