88	/// A writer that stops after `limit` bytes and says so in-band.
89	///
90	/// Beyond the bound this reports the bytes as consumed rather than returning a
91	/// short count: `tracing_appender` treats a short write as an I/O error, so a
92	/// truthful-but-short return would turn a size limit into a logging failure.
93	pub struct BoundedWriter<W: Write> {
94	    inner: W,
95	    remaining: u64,
96	    bounded: bool,
97	    announced: bool,
98	}
99	
100	#[derive(Debug)]
101	struct SharedWriteError {
102	    address: NonNull<AtomicBool>,
103	}
104	
105	// SAFETY: address points to one initialized atomic in a MAP_SHARED mapping.
106	// AtomicBool supplies synchronization, and the mapping remains live while any
107	// clone of WriteErrorLatch exists in this process.
108	unsafe impl Send for SharedWriteError {}
109	unsafe impl Sync for SharedWriteError {}
110	
111	impl Drop for SharedWriteError {
112	    fn drop(&mut self) {
113	        // SAFETY: this process owns this mapping, created with exactly this
114	        // address and length in WriteErrorLatch::new. A fork receives its own
115	        // Arc refcount and unmaps only its own process mapping on drop.
116	        unsafe {
117	            libc::munmap(self.address.as_ptr().cast(), mem::size_of::<AtomicBool>());
118	        }
119	    }
120	}
121	
122	/// A process-shared latch for errors a tracing formatter otherwise discards.
123	///
124	/// Ordinary runs initialize tracing after the container fork. A heap atomic
125	/// would therefore be copy-on-write: the writer child could record an error
126	/// that the parent publishing the manifest never observes. This anonymous
127	/// MAP_SHARED cell is created before that fork and is not inherited across the
128	/// guest exec.
129	#[derive(Clone, Debug)]
130	pub struct WriteErrorLatch {
131	    shared: Arc<SharedWriteError>,
132	}
133	
134	impl WriteErrorLatch {
135	    pub fn new() -> io::Result<Self> {
136	        // SAFETY: anonymous shared mapping, no fixed address and no backing fd.
137	        let address = unsafe {
138	            libc::mmap(
139	                std::ptr::null_mut(),
140	                mem::size_of::<AtomicBool>(),
141	                libc::PROT_READ | libc::PROT_WRITE,
142	                libc::MAP_SHARED | libc::MAP_ANONYMOUS,
143	                -1,
144	                0,
145	            )
146	        };
147	        if address == libc::MAP_FAILED {
148	            return Err(io::Error::last_os_error());
149	        }
150	        let address = NonNull::new(address.cast::<AtomicBool>())
151	            .expect("mmap returned a non-null non-failure address");
152	        // SAFETY: the fresh mapping is writable and suitably page-aligned.
153	        unsafe { address.as_ptr().write(AtomicBool::new(false)) };
154	        Ok(Self {
155	            shared: Arc::new(SharedWriteError { address }),
156	        })
157	    }
158	
159	    fn cell(&self) -> &AtomicBool {
160	        // SAFETY: the Arc keeps the initialized mapping live in this process.
161	        unsafe { self.shared.address.as_ref() }
162	    }
163	
164	    fn record_failure(&self) {
165	        self.cell().store(true, Ordering::Release);
166	    }
167	
168	    pub fn failed(&self) -> bool {
169	        self.cell().load(Ordering::Acquire)
170	    }
171	}
