173	/// Records every write or flush error before returning it to tracing.
174	///
175	/// tracing-subscriber intentionally treats formatter I/O as diagnostic-only
176	/// and discards these errors. Evidence cannot: a valid prefix with a lost tail
177	/// is incomplete even when that prefix still parses.
178	pub struct LatchedWriter<W> {
179	    inner: W,
180	    latch: WriteErrorLatch,
181	}
182	
183	impl<W> LatchedWriter<W> {
184	    pub fn new(inner: W, latch: WriteErrorLatch) -> Self {
185	        Self { inner, latch }
186	    }
187	}
188	
189	impl<W: Write> Write for LatchedWriter<W> {
190	    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
191	        match self.inner.write(buf) {
192	            Ok(0) if !buf.is_empty() => {
193	                self.latch.record_failure();
194	                Ok(0)
195	            }
196	            Ok(written) => Ok(written),
197	            Err(error) => {
198	                self.latch.record_failure();
199	                Err(error)
200	            }
201	        }
202	    }
203	
204	    fn flush(&mut self) -> io::Result<()> {
205	        self.inner.flush().inspect_err(|_| {
206	            self.latch.record_failure();
207	        })
208	    }
209	}
