211	impl<W: Write> BoundedWriter<W> {
212	    /// `limit == 0` disables the bound entirely.
213	    pub fn new(inner: W, limit: u64) -> Self {
214	        Self {
215	            inner,
216	            remaining: limit,
217	            bounded: limit != 0,
218	            announced: false,
219	        }
220	    }
221	}
222	
223	impl<W: Write> BoundedWriter<W> {
224	    /// Announce truncation the FIRST time bytes are actually discarded.
225	    ///
226	    /// Deferring this to the next `write` leaves a log that was truncated on
227	    /// its final write silent, which is the exact failure the marker exists to
228	    /// prevent -- caught end-to-end: a 100-byte bound produced exactly 100
229	    /// bytes and no marker, because no further write ever arrived.
230	    fn announce_truncation(&mut self) -> io::Result<()> {
231	        if !self.announced {
232	            self.announced = true;
233	            self.inner.write_all(TRUNCATION_MARKER)?;
234	            self.inner.flush()?;
235	        }
236	        Ok(())
237	    }
238	}
239	
240	impl<W: Write> Write for BoundedWriter<W> {
241	    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
242	        if !self.bounded {
243	            return self.inner.write(buf);
244	        }
245	        if self.remaining == 0 {
246	            self.announce_truncation()?;
247	            return Ok(buf.len());
248	        }
249	        let take = buf.len().min(self.remaining as usize);
250	        let written = self.inner.write(&buf[..take])?;
251	        self.remaining -= written as u64;
252	        if written < take {
253	            // A genuine short write by the inner writer: report it truthfully
254	            // and let the caller retry the remainder.
255	            return Ok(written);
256	        }
257	        if take < buf.len() {
258	            // This write is the one that crossed the bound; its tail is being
259	            // dropped, so say so now rather than hoping for another write.
260	            self.announce_truncation()?;
261	        }
262	        Ok(buf.len())
263	    }
264	
265	    fn flush(&mut self) -> io::Result<()> {
266	        self.inner.flush()
267	    }
268	}
