274	/// Keeps a nonblocking public writer alive when one is installed. A private
275	/// evidence layer is synchronous and therefore needs no drain worker or guard.
276	pub struct TracingGuard {
277	    _worker: Option<tracing_appender::non_blocking::WorkerGuard>,
278	}
279	
280	impl TracingGuard {
281	    fn synchronous() -> Self {
282	        Self { _worker: None }
283	    }
284	}
