286	/// Returns a non-blocking subscriber for logging to a file.
287	///
288	/// NOTE: Writes to `f` are unbuffered, so this may be slow.
289	fn file_subscriber<W: Write + Send + 'static>(
290	    level: LevelFilter,
291	    f: W,
292	) -> (impl Subscriber, tracing_appender::non_blocking::WorkerGuard) {
293	    let filter = env_filter(level);
294	    let (writer, guard) = tracing_appender::non_blocking(f);
295	
296	    let subscriber = tracing_subscriber::fmt()
297	        .with_env_filter(filter)
298	        .with_writer(writer)
299	        .with_ansi(false)
300	        .finish();
301	
302	    (subscriber, guard)
303	}
304	
305	/// A file subscriber whose writes CANNOT be lost when the process dies.
306	///
307	/// `file_subscriber` uses `tracing_appender::non_blocking`, which queues to a
308	/// background thread and only drains when its guard drops. A run that dies
309	/// without unwinding -- which is exactly what a fail-closed guest does -- never
310	/// drops the guard, so the QUEUED TAIL IS LOST. The tail is where a fatal
311	/// diagnostic lives, so the one line that explains the failure is the one line
312	/// reliably discarded.
313	///
314	/// MEASURED 2026-08-25 on c-programs/dbt-unsupported-syscall under `--verify`:
315	///   non-blocking  18 runs, diagnostic present 0 times, logs truncated at a
316	///                 RANDOM syscall each run (#5,#6,#10,#11,#16,#23,#27,#31...)
317	///                 and random sizes (5,482 / 7,632 / 10,123 / 15,546 bytes)
318	///   synchronous    4 runs, diagnostic present 4 times, every run reaching
319	///                 syscall #32 and producing an IDENTICAL 16,171-byte log
320	/// The randomness was the tell: a deterministic guest under a deterministic
321	/// engine cannot genuinely die at a different syscall each time.
322	///
323	/// COST, measured rather than assumed, on a 477 KB verify log:
324	/// synchronous 1.77s versus non-blocking 1.73s -- inside noise, identical
325	/// output size. The queue was buying nothing and losing the diagnostic.
326	fn sync_file_subscriber<W: Write + Send + 'static>(level: LevelFilter, f: W) -> impl Subscriber {
327	    let filter = env_filter(level);
328	    tracing_subscriber::fmt()
329	        .with_env_filter(filter)
330	        .with_writer(std::sync::Mutex::new(f))
331	        .with_ansi(false)
332	        .finish()
333	}
334	
335	/// Initializes SYNCHRONOUS tracing to `f`, for logs whose tail must survive a
336	/// crash. See [`sync_file_subscriber`].
337	pub fn init_sync_file_tracing<W: Write + Send + 'static>(
338	    level: Option<LevelFilter>,
339	    f: W,
340	) -> TracingGuard {
341	    // Match the PID/TID slot consumed by file tracing's worker and by the
342	    // stderr logger, while keeping verification evidence synchronous.
343	    equalize_tracing_thread_number();
344	    let level = level.unwrap_or(DEFAULT_TRACE_LEVEL);
345	    let subscriber = sync_file_subscriber(level, f);
346	    subscriber
347	        .try_init()
348	        .expect("global tracing subscriber to install");
349	    TracingGuard::synchronous()
350	}
