352	/// Initializes tracing to the given file `f`.
353	///
354	/// NOTE: Writes to `f` are unbuffered, so this may be slow.
355	#[must_use = "This function returns a guard that should not be immediately dropped"]
356	pub fn init_file_tracing<W: Write + Send + 'static>(
357	    level: Option<LevelFilter>,
358	    f: W,
359	) -> TracingGuard {
360	    let level = level.unwrap_or(DEFAULT_TRACE_LEVEL);
361	
362	    let (subscriber, guard) = file_subscriber(level, f);
363	
364	    subscriber
365	        .try_init()
366	        .expect("global tracing subscriber to install");
367	
368	    TracingGuard {
369	        _worker: Some(guard),
370	    }
371	}
