373	/// Preserve the public file logger while synchronously duplicating INFO-and-
374	/// higher events into a private evidence descriptor. This creates only the
375	/// public logger's existing nonblocking worker; the evidence writer is direct.
376	pub fn init_file_tracing_with_evidence<P, E>(
377	    level: Option<LevelFilter>,
378	    public: P,
379	    evidence: E,
380	) -> TracingGuard
381	where
382	    P: Write + Send + 'static,
383	    E: Write + Send + 'static,
384	{
385	    let (public_writer, guard) = tracing_appender::non_blocking(public);
386	    let public_layer = tracing_subscriber::fmt::layer()
387	        .with_writer(public_writer)
388	        .with_ansi(false)
389	        .with_filter(env_filter(level.unwrap_or(DEFAULT_TRACE_LEVEL)));
390	    let evidence_layer = tracing_subscriber::fmt::layer()
391	        .with_writer(std::sync::Mutex::new(evidence))
392	        .with_ansi(false)
393	        .with_filter(LevelFilter::INFO);
394	    tracing_subscriber::registry()
395	        .with(public_layer)
396	        .with(evidence_layer)
397	        .try_init()
398	        .expect("global tracing subscriber to install");
399	    TracingGuard {
400	        _worker: Some(guard),
401	    }
402	}
403	
404	fn equalize_tracing_thread_number() {
405	    // Create an extra, pointless thread just so that our thread number starts at the same DetTid
406	    // "3" that the `init_file_tracing` option does.
407	    std::thread::spawn(|| {}).join().unwrap();
408	}
409	
410	/// Preserve the public stderr logger while synchronously duplicating INFO-and-
411	/// higher events into a private evidence descriptor. The only spawned thread
412	/// is the same joined PID/TID equalization thread used without evidence.
413	pub fn init_stderr_tracing_with_evidence<E>(level: Option<LevelFilter>, evidence: E) -> TracingGuard
414	where
415	    E: Write + Send + 'static,
416	{
417	    equalize_tracing_thread_number();
418	    let public_layer = tracing_subscriber::fmt::layer()
419	        .with_writer(|| detcore::util::RetryingStderr)
420	        .with_ansi(stderr().is_terminal())
421	        .with_filter(env_filter(level.unwrap_or(DEFAULT_TRACE_LEVEL)));
422	    let evidence_layer = tracing_subscriber::fmt::layer()
423	        .with_writer(std::sync::Mutex::new(evidence))
424	        .with_ansi(false)
425	        .with_filter(LevelFilter::INFO);
426	    tracing_subscriber::registry()
427	        .with(public_layer)
428	        .with(evidence_layer)
429	        .try_init()
430	        .expect("global tracing subscriber to install");
431	    TracingGuard::synchronous()
432	}
433	
434	/// Returns a tracing subscriber that logs to `stderr`.
435	///
436	/// NOTE: Writes to stderr are unbuffered, so this may be slow.
437	pub fn stderr_subscriber(level: Option<LevelFilter>) -> impl Subscriber {
438	    let level = level.unwrap_or(DEFAULT_TRACE_LEVEL);
439	
440	    let filter = env_filter(level);
441	    tracing_subscriber::fmt()
442	        .with_env_filter(filter)
443	        // NOT `io::stderr`: a guest can set O_NONBLOCK on the inherited fd 2,
444	        // after which a full pipe makes these writes fail with EAGAIN. The fmt
445	        // layer discards the write error, so log lines would vanish with no
446	        // marker at all. `RetryingStderr` waits for the reader instead of
447	        // dropping, and does not alter the flag the guest set.
448	        .with_writer(|| detcore::util::RetryingStderr)
449	        .with_ansi(stderr().is_terminal())
450	        .finish()
451	}
452	
453	/// Initializes tracing to `stderr`.
454	///
455	/// NOTE: Writes to stderr are unbuffered, so this may be slow.
456	pub fn init_stderr_tracing(level: Option<LevelFilter>) {
457	    equalize_tracing_thread_number();
458	
459	    stderr_subscriber(level)
460	        .try_init()
461	        .expect("global tracing subscriber to install")
462	}
