468	    use super::*;
469	
470	    /// `log_max_bytes` reads the process environment, which libtest's threads
471	    /// share.
472	    static ENV_LOCK: Mutex<()> = Mutex::new(());
473	    struct FailingWriter {
474	        fail_write: bool,
475	    }
476	
477	    impl Write for FailingWriter {
478	        fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
479	            if self.fail_write {
480	                Err(io::Error::other("injected write failure"))
481	            } else {
482	                Ok(buf.len())
483	            }
484	        }
485	
486	        fn flush(&mut self) -> io::Result<()> {
487	            if self.fail_write {
