495	    #[test]
496	    fn private_writer_latches_write_and_flush_errors() {
497	        let write_latch = WriteErrorLatch::new().unwrap();
498	        let mut write_fails =
499	            LatchedWriter::new(FailingWriter { fail_write: true }, write_latch.clone());
500	        assert!(write_fails.write_all(b"record").is_err());
501	        assert!(write_latch.failed());
502	
503	        let flush_latch = WriteErrorLatch::new().unwrap();
504	        let mut flush_fails =
505	            LatchedWriter::new(FailingWriter { fail_write: false }, flush_latch.clone());
506	        assert!(flush_fails.flush().is_err());
507	        assert!(flush_latch.failed());
508	    }
