510	    #[test]
511	    fn private_writer_latch_is_visible_across_fork() {
512	        let latch = WriteErrorLatch::new().unwrap();
513	        // SAFETY: the child performs only an atomic store and _exit; it does no
514	        // allocation and acquires no process-local lock after this threaded
515	        // test harness forks.
516	        let pid = unsafe { libc::fork() };
517	        assert!(pid >= 0, "fork failed");
518	        if pid == 0 {
519	            latch.record_failure();
520	            unsafe { libc::_exit(0) };
521	        }
522	        let mut status = 0;
523	        assert_eq!(unsafe { libc::waitpid(pid, &mut status, 0) }, pid);
524	        assert_eq!(status, 0);
525	        assert!(
526	            latch.failed(),
527	            "a heap-only latch would lose the child writer failure"
528	        );
529	    }
