575	    }
576	
577	    /// The regression the unit tests originally missed and an end-to-end run
578	    /// caught: a log whose FINAL write crosses the bound must still announce
579	    /// itself. Deferring the marker to the next write left a 100-byte-bounded
580	    /// log at exactly 100 bytes with no marker at all.
581	    #[test]
582	    fn a_single_straddling_write_announces_without_a_following_write() {
583	        let mut sink: Vec<u8> = Vec::new();
584	        {
585	            let mut writer = BoundedWriter::new(&mut sink, 10);
586	            writer.write_all(&[b'q'; 40]).unwrap();
587	            // deliberately no further write
588	        }
589	        let text = String::from_utf8_lossy(&sink);
590	        assert_eq!(
591	            text.matches("HERMIT LOG TRUNCATED").count(),
592	            1,
593	            "a truncated final write must announce itself: {text}"
594	        );
595	        assert_eq!(sink.iter().filter(|b| **b == b'q').count(), 10);
596	    }
597	
598	    /// What this writer produces must be what the comparator recognizes.
599	    ///
600	    /// `detcore::logdiff` refuses to return a comparison verdict for a
601	    /// truncated log. If the bytes written here ever drift from what
602	    /// [`detcore::logdiff::log_was_truncated`] accepts, that refusal stops
603	    /// firing and a truncated pair silently returns to comparing only its
604	    /// prefix -- with nothing failing to say so. This test is the binding
605	    /// between them.
606	    ///
607	    /// It runs the REAL writer's output through the REAL predicate rather than
608	    /// comparing two constants, so it binds the anchoring as well as the text:
609	    /// the marker must survive as a whole line at end of file, which is what
610	    /// the comparator actually keys on. Drift in this file's literal or in
611	    /// detcore's constant or predicate all fail it.
612	    #[test]
613	    fn the_written_marker_is_the_text_the_comparator_matches() {
614	        let mut sink: Vec<u8> = Vec::new();
615	        {
616	            let mut writer = BoundedWriter::new(&mut sink, 64);
617	            // A realistic tail: whole "lines", the last of which straddles the
618	            // bound, so the marker has to terminate a partial line.
619	            for _ in 0..20 {
620	                writer
621	                    .write_all(b"2022-09-06T14:15:47.000000Z INFO detcore: DETLOG x\n")
622	                    .unwrap();
623	            }
624	            writer.flush().unwrap();
625	        }
626	        let written = String::from_utf8(sink).unwrap();
627	        assert!(
628	            detcore::logdiff::log_was_truncated(&written),
629	            "the bounded writer produced {written:?}, which detcore::logdiff does not classify \
630	             as truncated; a truncated pair would silently be compared on its prefix"
631	        );
632	
633	        // The other direction, so this cannot pass by the predicate accepting
634	        // everything: the same content under a bound it never reaches is NOT
635	        // truncated.
636	        let mut unbounded: Vec<u8> = Vec::new();
637	        {
638	            let mut writer = BoundedWriter::new(&mut unbounded, 0);
639	            writer
640	                .write_all(b"2022-09-06T14:15:47.000000Z INFO detcore: DETLOG x\n")
641	                .unwrap();
642	        }
643	        assert!(
644	            !detcore::logdiff::log_was_truncated(&String::from_utf8(unbounded).unwrap()),
645	            "an untruncated log must not be classified as truncated"
646	        );
647	    }
648	
649	    /// A malformed bound must be an error, not a silent 1 GiB.
650	    ///
651	    /// `HERMIT_LOG_MAX_BYTES=0` is the documented way to disable the bound, so
652	    /// a value that fails to parse must not quietly become the default: that
653	    /// would re-enable the bound for anyone who typed `unlimited`, `none`, or
654	    /// `1GiB` and reasonably believed it was off.
655	    ///
656	    /// Serialized against the other env-var cases in this file because the
657	    /// process environment is global; `log_max_bytes` reads it directly.
658	    #[test]
659	    fn a_malformed_bound_is_an_error_not_a_silent_default() {
660	        let _lock = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
661	        let restore = std::env::var(LOG_MAX_BYTES_ENV).ok();
662	
663	        // SAFETY: guarded by ENV_LOCK; no other thread in this test binary
664	        // reads the environment concurrently.
665	        unsafe {
666	            for bad in ["unlimited", "none", "1GiB", "-1", "", "1 000"] {
667	                std::env::set_var(LOG_MAX_BYTES_ENV, bad);
668	                assert!(
669	                    log_max_bytes().is_err(),
670	                    "{bad:?} must be rejected, not silently read as {DEFAULT_LOG_MAX_BYTES}"
671	                );
672	            }
673	            // Bracket the accepting direction, including the documented
674	            // "disable" value, so this is not a check that rejects everything.
675	            for (good, expected) in [("0", 0u64), ("4096", 4096), (" 4096 ", 4096)] {
676	                std::env::set_var(LOG_MAX_BYTES_ENV, good);
677	                assert_eq!(
678	                    log_max_bytes().unwrap(),
679	                    expected,
680	                    "{good:?} must be accepted"
681	                );
682	            }
683	            std::env::remove_var(LOG_MAX_BYTES_ENV);
684	            assert_eq!(
685	                log_max_bytes().unwrap(),
686	                DEFAULT_LOG_MAX_BYTES,
687	                "an unset variable is the only thing that means the default"
688	            );
689	            match restore {
690	                Some(v) => std::env::set_var(LOG_MAX_BYTES_ENV, v),
691	                None => std::env::remove_var(LOG_MAX_BYTES_ENV),
692	            }
693	        }
694	    }
695	
696	    /// The non-obvious correctness point: `tracing_appender` treats a short
697	    /// write as an I/O error, so a discarding writer must still report the
698	    /// caller's whole buffer as consumed.
699	    #[test]
700	    fn a_write_straddling_the_bound_reports_full_consumption() {
701	        let mut sink: Vec<u8> = Vec::new();
702	        let mut writer = BoundedWriter::new(&mut sink, 5);
703	        assert_eq!(writer.write(&[b'y'; 40]).unwrap(), 40);
704	    }
705	}
