4998	/// Represents a tmpfs location. There are different ways to construct `/tmp` for
4999	/// the container and this encapsulates all of them.
5000	enum Tmpfs<'a> {
5001	    /// Use an existing path as `/tmp`.
5002	    Path(&'a Path),
5003	
5004	    /// Use a new temporary directory as `/tmp`.
5005	    Temp(tempfile::TempDir),
5006	}
5007	
5008	impl<'a> Tmpfs<'a> {
5009	    /// Returns the path to `/tmp`.
5010	    pub fn path(&self) -> &Path {
5011	        match self {
5012	            Self::Path(path) => path,
