1264	+    ssize_t size = read(info, text, sizeof(text) - 1);
1265	+    CHECK(size > 0 && size < (ssize_t)sizeof(text) - 1);
1266	+    CHECK(close(info) == 0);
1267	+    text[size] = '\0';
1268	+    const char *line = strstr(text, "\nino:\t");
1269	+    CHECK(line != NULL);
1270	+    char *end;
1271	+    unsigned long long inode = strtoull(line + strlen("\nino:\t"), &end, 10);
1272	+    CHECK(*end == '\n' && inode == (unsigned long long)expected.st_ino);
1273	+}
1274	+
1275	+static void check_pipe_link(int fd, struct stat expected) {
1276	+    char path[64], text[128], wanted[128];
1277	+    CHECK(snprintf(path, sizeof(path), "/proc/self/fd/%d", fd) > 0);
1278	+    ssize_t size = readlink(path, text, sizeof(text) - 1);
1279	+    CHECK(size > 0 && size < (ssize_t)sizeof(text) - 1);
1280	+    text[size] = '\0';
1281	+    CHECK(snprintf(wanted, sizeof(wanted), "pipe:[%llu]",
1282	+                   (unsigned long long)expected.st_ino) > 0);
1283	+    CHECK(strcmp(text, wanted) == 0);
1284	+}
1285	+
1286	+typedef struct stat (*OrdinaryStat)(int fd);
1287	+
1288	+static void check_reuse(const int saved[3], const struct stat initial[3],
1289	+                        OrdinaryStat stat_object) {
1290	+    char path_a[] = "stdio-inode-a-XXXXXX";
1291	+    char path_b[] = "stdio-inode-b-XXXXXX";
1292	+    int file_a = mkstemp(path_a), file_b = mkstemp(path_b);
1293	+    CHECK(file_a >= 3 && file_b >= 3);
1294	+    struct stat identity_a = stat_object(file_a);
1295	+    struct stat identity_b = stat_object(file_b);
1296	+    CHECK(identity_a.st_dev == identity_b.st_dev);
1297	+    CHECK(identity_a.st_ino != identity_b.st_ino);
1298	+
1299	+    /* AT_EMPTY_PATH does not turn a nonempty pathname into a descriptor stat. */
1300	+    char cwd[3072], absolute_a[4096];
1301	+    CHECK(getcwd(cwd, sizeof(cwd)) != NULL);
1302	+    int path_size = snprintf(absolute_a, sizeof(absolute_a), "%s/%s", cwd, path_a);
1303	+    CHECK(path_size > 0 && (size_t)path_size < sizeof(absolute_a));
1304	+    struct stat absolute_stat;
1305	+    CHECK(syscall(SYS_newfstatat, saved[1], absolute_a, &absolute_stat,
1306	+                  AT_EMPTY_PATH) == 0);
1307	+    CHECK(same_object(absolute_stat, identity_a));
1308	+    struct statx absolute_statx;
1309	+    CHECK(syscall(SYS_statx, saved[1], absolute_a, AT_EMPTY_PATH,
1310	+                  STATX_BASIC_STATS, &absolute_statx) == 0);
1311	+    check_statx_identity(absolute_statx, identity_a);
1312	+
1313	+    for (int low = 0; low < 3; ++low) {
1314	+        CHECK(close(low) == 0);
1315	+        CHECK(open(path_a, O_RDWR) == low);
1316	+        struct stat opened_a = stat_object(low), path_stat;
1317	+        CHECK(same_object(opened_a, identity_a));
1318	+        CHECK(syscall(SYS_newfstatat, AT_FDCWD, path_a, &path_stat, 0) == 0);
1319	+        CHECK(same_object(opened_a, path_stat));
1320	+        int alias = dup(low);
1321	+        CHECK(alias >= 3);
1322	+        CHECK(same_object(opened_a, stat_object(alias)));
1323	+        check_fdinfo(low, opened_a);
1324	+        check_fdinfo(alias, opened_a);
1325	+
1326	+        CHECK(close(low) == 0);
1327	+        CHECK(open(path_b, O_RDWR) == low);
1328	+        struct stat opened_b = stat_object(low);
1329	+        CHECK(same_object(opened_b, identity_b));
1330	+        CHECK(!same_object(opened_a, opened_b));
1331	+        CHECK(same_object(opened_a, stat_object(alias)));
1332	+        check_fdinfo(low, opened_b);
1333	+        CHECK(close(alias) == 0);
1334	+        CHECK(dup2(saved[low], low) == low);
1335	+        CHECK(same_object(initial[low], stat_fd(low)));
1336	+    }
1337	+
1338	+    for (int low = 0; low < 3; ++low) {
1339	+        CHECK(close(low) == 0);
1340	+        int pipe_fds[2];
1341	+        CHECK(pipe(pipe_fds) == 0 && pipe_fds[0] == low);
1342	+        struct stat pipe_identity = stat_object(pipe_fds[0]);
1343	+        int pipe_alias = dup(pipe_fds[0]);
1344	+        CHECK(pipe_alias >= 3);
1345	+        CHECK(same_object(pipe_identity, stat_object(pipe_alias)));
1346	+        check_fdinfo(pipe_fds[0], pipe_identity);
1347	+        check_fdinfo(pipe_alias, pipe_identity);
1348	+        check_pipe_link(pipe_fds[0], pipe_identity);
1349	+        check_pipe_link(pipe_alias, pipe_identity);
1350	+        CHECK(close(pipe_alias) == 0);
1351	+        CHECK(close(pipe_fds[0]) == 0);
1352	+        CHECK(close(pipe_fds[1]) == 0);
1353	+        CHECK(dup2(saved[low], low) == low);
1354	+        CHECK(same_object(initial[low], stat_fd(low)));
1355	+    }
1356	+
1357	+    CHECK(close(file_a) == 0 && close(file_b) == 0);
1358	+    CHECK(unlink(path_a) == 0 && unlink(path_b) == 0);
1359	+}
1360	+
1361	+int main(int argc, char **argv) {
1362	+    CHECK(argc == 2);
1363	+    OrdinaryStat stat_object = NULL;
1364	+    if (strcmp(argv[1], "descriptor-reuse") == 0) {
1365	+        stat_object = stat_ordinary_descriptor;
1366	+    } else if (strcmp(argv[1], "complete-stat-routes") == 0) {
1367	+        stat_object = stat_complete_routes;
1368	+    }
1369	+    CHECK(stat_object != NULL);
1370	+    int saved[3];
1371	+    struct stat initial[3];
1372	+    for (int fd = 0; fd < 3; ++fd) {
1373	+        initial[fd] = stat_fd(fd);
1374	+        saved[fd] = fcntl(fd, F_DUPFD_CLOEXEC, 10);
1375	+        CHECK(saved[fd] >= 10);
1376	+    }
1377	+    report_fd = saved[2];
1378	+    check_stat_errors(saved[1]);
1379	+    check_reuse(saved, initial, stat_object);
1380	+    for (int fd = 0; fd < 3; ++fd) {
1381	+        CHECK(close(saved[fd]) == 0);
1382	+    }
1383	+    report_fd = STDERR_FILENO;
1384	+    CHECK(printf("stdio-inode-%s-ok\n", argv[1]) > 0);
1385	+    return 0;
1386	+}
